320	// ── Request types ─────────────────────────────────────────────────
321	
322	type EmailRequest =
323	  | { type: "welcome"; to: string; data: WelcomeData }
324	  | { type: "scan_complete"; to: string; data: ScanCompleteData }
325	  | { type: "weekly_digest"; to: string; data: WeeklyDigestData }
326	  | { type: "team_invite"; to: string; data: TeamInviteData };
327	
328	// ── Resend call ───────────────────────────────────────────────────
329	
330	async function sendViaResend(
331	  to: string,
332	  subject: string,
333	  html: string,
334	): Promise<void> {
335	  const apiKey = Deno.env.get("RESEND_API_KEY");
336	  if (!apiKey) {
337	    throw new Error("RESEND_API_KEY env var is not set");
338	  }
339	
340	  const res = await fetch("https://api.resend.com/emails", {
341	    method: "POST",
342	    headers: {
343	      "Authorization": `Bearer ${apiKey}`,
344	      "Content-Type": "application/json",
345	    },
346	    body: JSON.stringify({
347	      from: FROM_ADDRESS,
348	      to,
349	      subject,
350	      html,
351	    }),
352	  });
353	
354	  if (!res.ok) {
355	    const body = await res.text();
356	    throw new Error(`Resend API error ${res.status}: ${body.slice(0, 300)}`);
357	  }
358	}
359	
360	// ── Main handler ──────────────────────────────────────────────────
361	
362	serve(async (req: Request) => {
363	  if (req.method === "OPTIONS") {
364	    return new Response("ok", { headers: corsHeaders });
365	  }
366	
367	  if (req.method !== "POST") {
368	    return jsonResponse({ error: "Method not allowed" }, 405);
369	  }
370	
371	  const appUrl = Deno.env.get("APP_URL") ?? Deno.env.get("SITE_URL") ?? "https://app.convertscan.com";
372	
373	  let payload: EmailRequest;
374	  try {
375	    payload = await req.json() as EmailRequest;
376	  } catch {
377	    return jsonResponse({ error: "Invalid JSON body" }, 400);
378	  }
379	
380	  if (!payload.type || !payload.to) {
381	    return jsonResponse({ error: "type and to are required" }, 400);
382	  }
383	
384	  let subject: string;
385	  let html: string;
386	
387	  try {
388	    switch (payload.type) {
389	      case "welcome": {
390	        const result = buildWelcomeEmail(payload.to, payload.data, appUrl);
391	        subject = result.subject;
392	        html = result.html;
393	        break;
394	      }
395	      case "scan_complete": {
396	        const result = buildScanCompleteEmail(payload.to, payload.data, appUrl);
397	        subject = result.subject;
398	        html = result.html;
399	        break;
400	      }
401	      case "weekly_digest": {
402	        const result = buildWeeklyDigestEmail(payload.to, payload.data, appUrl);
403	        subject = result.subject;
404	        html = result.html;
405	        break;
406	      }
407	      case "team_invite": {
408	        const result = buildTeamInviteEmail(payload.to, payload.data);
409	        subject = result.subject;
410	        html = result.html;
411	        break;
412	      }
413	      default: {
414	        return jsonResponse({ error: `Unknown email type: ${(payload as { type: string }).type}` }, 400);
415	      }
416	    }
417	  } catch (err) {
418	    console.error("Email template build failed:", err);
419	    return jsonResponse({ error: "Failed to build email template" }, 500);
420	  }
421	
422	  try {
423	    await sendViaResend(payload.to, subject, html);
424	    return jsonResponse({ status: "sent", type: payload.type, to: payload.to });
425	  } catch (err) {
426	    console.error("Resend delivery failed:", err);
427	    return jsonResponse(
428	      { error: "Email delivery failed", detail: err instanceof Error ? err.message : "unknown" },
429	      500,
430	    );
431	  }
432	});
