1	import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
2	import supabase from "@/lib/supabase";
3	import { useAuth } from "@/contexts/AuthContext";
4	import type { UserProfile } from "@/types";
5	import type { ProfileUpdate } from "@/types/database";
6	
7	// ── Query keys ──────────────────────────────────────────────────
8	
9	export const profileKeys = {
10	  all: ["profile"] as const,
11	  byUser: (userId: string) => ["profile", userId] as const,
12	};
13	
14	// ── useProfile ──────────────────────────────────────────────────
15	
16	export function useProfile() {
17	  const { user } = useAuth();
18	
19	  return useQuery({
20	    queryKey: profileKeys.byUser(user?.id ?? ""),
21	    queryFn: async (): Promise<UserProfile | null> => {
22	      if (!user?.id) return null;
23	
24	      const { data, error } = await supabase
25	        .from("profiles")
26	        .select(
27	          "id, email, full_name, company_name, website_url, avatar_url, plan, scans_used, scan_limit, created_at, billing_cycle_end"
28	        )
29	        .eq("id", user.id)
30	        .single();
31	
32	      if (error) {
33	        if (error.code === "PGRST116") return null; // row not found
34	        throw new Error(error.message);
35	      }
36	
37	      return data as UserProfile;
38	    },
39	    enabled: !!user?.id,
40	    staleTime: 1000 * 60 * 2, // 2 minutes
41	  });
42	}
43	
44	// ── useUpdateProfile ────────────────────────────────────────────
45	
46	type ProfileUpdatableFields = Pick<
47	  ProfileUpdate,
48	  "full_name" | "company_name" | "website_url" | "avatar_url"
49	>;
50	
51	export function useUpdateProfile() {
52	  const { user, refreshProfile } = useAuth();
53	  const queryClient = useQueryClient();
54	
55	  return useMutation({
56	    mutationFn: async (updates: ProfileUpdatableFields) => {
57	      if (!user?.id) throw new Error("Not authenticated");
58	
59	      const { data, error } = await supabase
60	        .from("profiles")
61	        .update({ ...updates, updated_at: new Date().toISOString() })
62	        .eq("id", user.id)
63	        .select(
64	          "id, email, full_name, company_name, website_url, avatar_url, plan, scans_used, scan_limit, created_at, billing_cycle_end"
65	        )
66	        .single();
67	
68	      if (error) throw new Error(error.message);
69	      return data as UserProfile;
70	    },
71	    onSuccess: (data) => {
72	      // Update React Query cache
73	      if (user?.id) {
74	        queryClient.setQueryData(profileKeys.byUser(user.id), data);
75	      }
76	      // Also refresh the AuthContext profile so header/sidebar updates
77	      refreshProfile();
78	    },
79	  });
80	}
