input.content:
/**
 * email-scheduler — Edge Function (cron-triggered daily)
 *
 * Handles three automated email sequences:
 *   1. Onboarding drip  — day 3 tips, day 7 case study
 *   2. Weekly digest    — Monday summary for active users (digest preference on)
 *   3. Win-back        — 14-day inactivity nudge (marketing preference on)
 *
 * Uses email_events table for idempotency — each sequence only fires once
 * per the defined window per user.
 *
 * Required env vars:
 *   SUPABASE_URL              — Supabase project URL
 *   SUPABASE_SERVICE_ROLE_KEY — Service role key (bypasses RLS)
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

// ── Types ─────────────────────────────────────────────────────────

interface ProfileRecord {
  id: string;
  email: string;
  full_name: string;
  created_at: string;
  email_preferences: Record<string, boolean> | null;
}

interface ScanCountResult {
  user_id: string;
  scan_count: number;
  avg_score: number;
  top_url: string | null;
}

// ── Supabase admin client ─────────────────────────────────────────

function getAdminClient() {
  const url = Deno.env.get("SUPABASE_URL");
  const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!url || !key) throw new Error("Missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY");
  return createClient(url, key, { auth: { autoRefreshToken: false, persistSession: false } });
}

// ── Send-email invoker ────────────────────────────────────────────

async function invokeEmailFunction(
  supabase: ReturnType<typeof createClient>,
  payload: Record<string, unknown>,
): Promise<void> {
  const { error } = await supabase.functions.invoke("send-email", { body: payload });
  if (error) throw new Error(`send-email invoke failed: ${error.message}`);
}

// ── Email event helpers ───────────────────────────────────────────

async function hasEmailEvent(
  supabase: ReturnType<typeof createClient>,
  userId: string,
  emailType: string,
  withinDays: number,
): Promise<boolean> {
  const cutoff = new Date();
  cutoff.setDate(cutoff.getDate() - withinDays);

  const { data, error } = await supabase
    .from("email_events")
    .select("id")
    .eq("user_id", userId)
    .eq("email_type", emailType)
    .gte("sent_at", cutoff.toISOString())
    .limit(1);

  if (error) throw new Error(`email_events query failed: ${error.message}`);
  return (data?.length ?? 0) > 0;
}

async function recordEmailEvent(
  supabase: ReturnType<typeof createClient>,
  userId: string,
  emailType: string,
): Promise<void> {
  const { error } = await supabase
    .from("email_events")
    .insert({ user_id: userId, email_type: emailType, sent_at: new Date().toISOString() });
  if (error) throw new Error(`email_events insert failed: ${error.message}`);
}

// ── Sequence: Onboarding drip ─────────────────────────────────────

async function runOnboardingDrip(supabase: ReturnType<typeof createClient>): Promise<void> {
  const now = new Date();

  // Day-3 window: created 3–4 days ago
  const day3Start = new Date(now);
  day3Start.setDate(day3Start.getDate() - 4);
  const day3End = new Date(now);
  day3End.setDate(day3End.getDate() - 3);

  // Day-7 window: created 7–8 days ago
  const day7Start = new Date(now);
  day7Start.setDate(day7Start.getDate() - 8);
  const day7End = new Date(now);
  day7End.setDate(day7End.getDate() - 7);

  const { data: allProfiles, error } = await supabase
    .from("profiles")
    .select("id, email, full_name, created_at, email_preferences")
    .or(
      `and(created_at.gte.${day3Start.toISOString()},created_at.lt.${day3End.toISOString()}),` +
      `and(created_at.gte.${day7Start.toISOString()},created_at.lt.${day7End.toISOString()})`,
    );

  if (error) throw new Error(`profiles query failed: ${error.message}`);

  const profiles = (allProfiles ?? []) as ProfileRecord[];

  for (const profile of profiles) {
    const createdAt = new Date(profile.created_at);
    const daysSinceSignup = Math.floor((now.getTime() - createdAt.getTime()) / (1000 * 60 * 60 * 24));

    if (daysSinceSignup >= 3 && daysSinceSignup < 4) {
      const alreadySent = await hasEmailEvent(supabase, profile.id, "onboarding_day3", 365);
      if (!alreadySent) {
        await invokeEmailFunction(supabase, {
          type: "onboarding_day3",
          to: profile.email,
          data: { name: profile.full_name ?? profile.email },
        });
        await recordEmailEvent(supabase, profile.id, "onboarding_day3");
      }
    } else if (daysSinceSignup >= 7 && daysSinceSignup < 8) {
      const alreadySent = await hasEmailEvent(supabase, profile.id, "onboarding_day7", 365);
      if (!alreadySent) {
        await invokeEmailFunction(supabase, {
          type: "onboarding_day7",
          to: profile.email,
          data: { name: profile.full_name ?? profile.email },
        });
        await recordEmailEvent(supabase, profile.id, "onboarding_day7");
      }
    }
  }
}

// ── Sequence: Weekly digest (Mondays only) ────────────────────────

async function runWeeklyDigest(supabase: ReturnType<typeof createClient>): Promise<void> {
  // Only run on Mondays (0 = Sunday, 1 = Monday)
  if (new Date().getDay() !== 1) return;

  const thirtyDaysAgo = new Date();
  thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

  const sevenDaysAgo = new Date();
  sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

  // Get users with scans in last 30 days who have digest preference on
  const { data: profilesRaw, error: profileError } = await supabase
    .from("profiles")
    .select("id, email, full_name, email_preferences");

  if (profileError) throw new Error(`profiles query failed: ${profileError.message}`);

  const profiles = ((profilesRaw ?? []) as ProfileRecord[]).filter((p) => {
    const prefs = p.email_preferences ?? {};
    return prefs["digest"] !== false; // default on if null/undefined
  });

  if (profiles.length === 0) return;

  const profileIds = profiles.map((p) => p.id);

  // Get scan stats per user for last 7 days
  const { data: scanData, error: scanError } = await supabase
    .from("scans")
    .select("user_id, overall_score, url, created_at")
    .in("user_id", profileIds)
    .eq("status", "completed")
    .gte("created_at", sevenDaysAgo.toISOString());

  if (scanError) throw new Error(`scans query failed: ${scanError.message}`);

  // Also check active in last 30 days
  const { data: activeData, error: activeError } = await supabase
    .from("scans")
    .select("user_id")
    .in("user_id", profileIds)
    .gte("created_at", thirtyDaysAgo.toISOString())
    .limit(1000);

  if (activeError) throw new Error(`active scans query failed: ${activeError.message}`);

  const activeUserIds = new Set((activeData ?? []).map((s: { user_id: string }) => s.user_id));

  // Build per-user stats
  const statsByUser = new Map<string, ScanCountResult>();
  for (const scan of scanData ?? []) {
    const s = scan as { user_id: string; overall_score: number | null; url: string };
    if (!statsByUser.has(s.user_id)) {
      statsByUser.set(s.user_id, { user_id: s.user_id, scan_count: 0, avg_score: 0, top_url: null });
    }
    const entry = statsByUser.get(s.user_id)!;
    entry.scan_count += 1;
    if (s.overall_score !== null) {
      entry.avg_score = Math.round(
        (entry.avg_score * (entry.scan_count - 1) + s.overall_score) / entry.scan_count,
      );
    }
    if (!entry.top_url) entry.top_url = s.url;
  }

  for (const profile of profiles) {
    if (!activeUserIds.has(profile.id)) continue;

    const alreadySent = await hasEmailEvent(supabase, profile.id, "weekly_digest", 6);
    if (alreadySent) continue;

    const stats = statsByUser.get(profile.id);

    await invokeEmailFunction(supabase, {
      type: "weekly_digest",
      to: profile.email,
      data: {
        name: profile.full_name ?? profile.email,
        scans_this_week: stats?.scan_count ?? 0,
        avg_score: stats?.avg_score ?? 0,
        top_url: stats?.top_url ?? null,
      },
    });
    await recordEmailEvent(supabase, profile.id, "weekly_digest");
  }
}

// ── Sequence: Win-back ────────────────────────────────────────────

async function runWinBack(supabase: ReturnType<typeof createClient>): Promise<void> {
  const fourteenDaysAgo = new Date();
  fourteenDaysAgo.setDate(fourteenDaysAgo.getDate() - 14);

  const thirtyDaysAgo = new Date();
  thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

  // Get profiles with marketing preference on
  const { data: profilesRaw, error: profileError } = await supabase
    .from("profiles")
    .select("id, email, full_name, created_at, email_preferences")
    .lt("created_at", fourteenDaysAgo.toISOString()); // only users older than 14 days

  if (profileError) throw new Error(`profiles query failed: ${profileError.message}`);

  const profiles = ((profilesRaw ?? []) as ProfileRecord[]).filter((p) => {
    const prefs = p.email_preferences ?? {};
    return prefs["marketing"] !== false; // default on if null/undefined
  });

  if (profiles.length === 0) return;

  const profileIds = profiles.map((p) => p.id);

  // Find users who HAVE had scans in last 14 days (to exclude them)
  const { data: recentScans, error: recentError } = await supabase
    .from("scans")
    .select("user_id")
    .in("user_id", profileIds)
    .gte("created_at", fourteenDaysAgo.toISOString());

  if (recentError) throw new Error(`recent scans query failed: ${recentError.message}`);

  const recentActiveIds = new Set((recentScans ?? []).map((s: { user_id: string }) => s.user_id));

  // Find users who have at least one scan ever (were active at some point)
  const { data: everActive, error: everError } = await supabase
    .from("scans")
    .select("user_id")
    .in("user_id", profileIds)
    .limit(5000);

  if (everError) throw new Error(`ever active query failed: ${everError.message}`);

  const everActiveIds = new Set((everActive ?? []).map((s: { user_id: string }) => s.user_id));

  for (const profile of profiles) {
    // Skip if recently active or never ran a scan
    if (recentActiveIds.has(profile.id)) continue;
    if (!everActiveIds.has(profile.id)) continue;

    const alreadySent = await hasEmailEvent(supabase, profile.id, "win_back", 30);
    if (alreadySent) continue;

    await invokeEmailFunction(supabase, {
      type: "win_back",
      to: profile.email,
      data: { name: profile.full_name ?? profile.email },
    });
    await recordEmailEvent(supabase, profile.id, "win_back");
  }
}

// ── Main handler ──────────────────────────────────────────────────

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  let supabase: ReturnType<typeof createClient>;
  try {
    supabase = getAdminClient();
  } catch (err) {
    return new Response(
      JSON.stringify({ error: err instanceof Error ? err.message : "Config error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }

  const results: Record<string, string> = {};

  try {
    await runOnboardingDrip(supabase);
    results["onboarding_drip"] = "ok";
  } catch (err) {
    results["onboarding_drip"] = err instanceof Error ? err.message : "error";
  }

  try {
    await runWeeklyDigest(supabase);
    results["weekly_digest"] = "ok";
  } catch (err) {
    results["weekly_digest"] = err instanceof Error ? err.message : "error";
  }

  try {
    await runWinBack(supabase);
    results["win_back"] = "ok";
  } catch (err) {
    results["win_back"] = err instanceof Error ? err.message : "error";
  }

  return new Response(JSON.stringify({ status: "completed", sequences: results }), {
    status: 200,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
});

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import type { Referral } from "@/types";
import type { ReferralInsert } from "@/types/database";

// ── Query keys ────────────────────────────────────────────────────

export const referralKeys = {
  all: ["referrals"] as const,
  byUser: (userId: string) => ["referrals", userId] as const,
  code: (userId: string) => ["referral-code", userId] as const,
};

// ── useReferrals ──────────────────────────────────────────────────
// Fetches all referrals the current user has made.

export function useReferrals() {
  const { user } = useAuth();

  return useQuery({
    queryKey: referralKeys.byUser(user?.id ?? ""),
    queryFn: async (): Promise<Referral[]> => {
      if (!user?.id) return [];

      const { data, error } = await supabase
        .from("referrals")
        .select("*")
        .eq("referrer_id", user.id)
        .order("created_at", { ascending: false });

      if (error) throw new Error(error.message);
      return (data ?? []) as Referral[];
    },
    enabled: !!user?.id,
    staleTime: 1000 * 60 * 2,
  });
}

// ── useReferralStats ──────────────────────────────────────────────
// Derived stats from the referrals list.

export function useReferralStats() {
  const { data: referrals = [], isLoading, isError } = useReferrals();

  const totalReferred = referrals.length;
  const signedUp = referrals.filter((r) => r.status === "signed_up" || r.status === "converted" || r.status === "rewarded").length;
  const converted = referrals.filter((r) => r.status === "converted" || r.status === "rewarded").length;
  const rewarded = referrals.filter((r) => r.status === "rewarded").length;

  return { totalReferred, signedUp, converted, rewarded, isLoading, isError };
}

// ── useReferralCode ───────────────────────────────────────────────
// Returns the user's referral code. Generates one via profile update if null.

export function useReferralCode() {
  const { user, profile, refreshProfile } = useAuth();
  const queryClient = useQueryClient();

  const generateCode = useMutation({
    mutationFn: async (): Promise<string> => {
      if (!user?.id) throw new Error("Not authenticated");

      // Generate a short random code: 8 alphanumeric chars
      const chars = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789";
      let code = "";
      for (let i = 0; i < 8; i++) {
        code += chars[Math.floor(Math.random() * chars.length)];
      }

      const { data, error } = await supabase
        .from("profiles")
        .update({ referral_code: code })
        .eq("id", user.id)
        .select("referral_code")
        .single();

      if (error) throw new Error(error.message);
      return (data as { referral_code: string }).referral_code;
    },
    onSuccess: () => {
      void refreshProfile();
      void queryClient.invalidateQueries({ queryKey: referralKeys.code(user?.id ?? "") });
    },
    onError: (error: unknown) => {
      const message = error instanceof Error ? error.message : "Failed to generate referral code";
      toast.error(message);
    },
  });

  return {
    code: profile?.referral_code ?? null,
    isGenerating: generateCode.isPending,
    generate: generateCode.mutate,
  };
}

// ── useCreateReferral ─────────────────────────────────────────────
// Creates a referral row after signup when a ?ref= code was used.

export function useCreateReferral() {
  return useMutation({
    mutationFn: async ({
      referrerCode,
      referredEmail,
      referredId,
    }: {
      referrerCode: string;
      referredEmail: string;
      referredId: string;
    }): Promise<void> => {
      // Look up the referrer by their code
      const { data: referrer, error: lookupError } = await supabase
        .from("profiles")
        .select("id")
        .eq("referral_code", referrerCode)
        .single();

      if (lookupError || !referrer) {
        // Silently fail — invalid referral code should not block signup
        return;
      }

      const insert: ReferralInsert = {
        referrer_id: referrer.id,
        referred_email: referredEmail,
        referred_id: referredId,
        status: "signed_up",
      };

      const { error: insertError } = await supabase.from("referrals").insert(insert);

      if (insertError) throw new Error(insertError.message);
    },
  });
}

