import { useState } from "react";
import { Twitter, Linkedin, Copy, Check, Gift, Users, UserCheck, TrendingUp, ExternalLink } from "lucide-react";
import { toast } from "sonner";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { PageHeader } from "@/components/shared/PageHeader";
import { PageTransition } from "@/components/shared/PageTransition";
import { ErrorState } from "@/components/shared/ErrorState";
import { useReferrals, useReferralStats, useReferralCode } from "@/hooks/use-referrals";
import type { Referral } from "@/types";

// ── Status badge ──────────────────────────────────────────────────

const STATUS_CLASSES: Record<Referral["status"], string> = {
  pending: "bg-slate-100 text-slate-600",
  signed_up: "bg-blue-100 text-blue-700",
  converted: "bg-indigo-100 text-indigo-700",
  rewarded: "bg-green-100 text-green-700",
};

const STATUS_LABELS: Record<Referral["status"], string> = {
  pending: "Invited",
  signed_up: "Signed up",
  converted: "Converted",
  rewarded: "Rewarded",
};

// ── Referral link card ────────────────────────────────────────────

function ReferralLinkCard() {
  const { code, isGenerating, generate } = useReferralCode();
  const [copied, setCopied] = useState(false);

  const referralUrl = code
    ? `${window.location.origin}/signup?ref=${code}`
    : null;

  const handleCopy = async () => {
    if (!referralUrl) return;
    await navigator.clipboard.writeText(referralUrl);
    setCopied(true);
    toast.success("Referral link copied!");
    setTimeout(() => setCopied(false), 2000);
  };

  const twitterText = encodeURIComponent(
    `I've been using ConvertScan to improve my conversion rates with AI-powered CRO audits. Try it free:`,
  );
  const twitterUrl = referralUrl ? `https://twitter.com/intent/tweet?text=${twitterText}&url=${encodeURIComponent(referralUrl)}` : null;

  const linkedinUrl = referralUrl
    ? `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(referralUrl)}`
    : null;

  return (
    <Card className="border-border/50 shadow-soft">
      <CardHeader>
        <CardTitle className="text-base">Your referral link</CardTitle>
        <CardDescription>Share this link. When someone signs up and converts, you earn a reward.</CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {code ? (
          <>
            <div className="flex items-center gap-2 rounded-lg border border-border/50 bg-muted/30 p-3">
              <code className="flex-1 truncate text-sm text-foreground select-all font-mono">
                {referralUrl}
              </code>
              <Button
                size="sm"
                variant="outline"
                className="shrink-0 border-border/50"
                onClick={handleCopy}
              >
                {copied ? (
                  <><Check className="mr-1.5 h-3.5 w-3.5 text-green-500" />Copied</>
                ) : (
                  <><Copy className="mr-1.5 h-3.5 w-3.5" />Copy</>
                )}
              </Button>
            </div>
            <div className="flex flex-wrap gap-2">
              {twitterUrl && (
                <Button
                  variant="outline"
                  size="sm"
                  className="border-border/50 gap-1.5"
                  onClick={() => window.open(twitterUrl, "_blank", "noopener,noreferrer")}
                >
                  <Twitter className="h-3.5 w-3.5" />
                  Share on X
                  <ExternalLink className="h-3 w-3 text-muted-foreground" />
                </Button>
              )}
              {linkedinUrl && (
                <Button
                  variant="outline"
                  size="sm"
                  className="border-border/50 gap-1.5"
                  onClick={() => window.open(linkedinUrl, "_blank", "noopener,noreferrer")}
                >
                  <Linkedin className="h-3.5 w-3.5" />
                  Share on LinkedIn
                  <ExternalLink className="h-3 w-3 text-muted-foreground" />
                </Button>
              )}
            </div>
          </>
        ) : (
          <div className="text-center py-4">
            <p className="text-sm text-muted-foreground mb-3">
              Generate your unique referral link to start earning rewards.
            </p>
            <Button onClick={() => generate()} disabled={isGenerating}>
              {isGenerating ? "Generating…" : "Generate my referral link"}
            </Button>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

// ── Stats cards ───────────────────────────────────────────────────

function ReferralStatsCards() {
  const { totalReferred, signedUp, converted, isLoading } = useReferralStats();

  const stats = [
    { label: "Total referred", value: totalReferred, icon: Users, color: "text-slate-600" },
    { label: "Signed up", value: signedUp, icon: UserCheck, color: "text-blue-600" },
    { label: "Converted", value: converted, icon: TrendingUp, color: "text-indigo-600" },
  ];

  if (isLoading) {
    return (
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        {stats.map((_, i) => (
          <Skeleton key={i} className="h-24 rounded-xl" />
        ))}
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
      {stats.map((stat) => (
        <Card key={stat.label} className="border-border/50 shadow-soft">
          <CardContent className="p-5">
            <div className="flex items-center justify-between mb-3">
              <p className="text-xs font-medium text-muted-foreground">{stat.label}</p>
              <stat.icon className={`h-4 w-4 ${stat.color}`} />
            </div>
            <p className="text-3xl font-bold text-foreground tabular-nums">{stat.value}</p>
          </CardContent>
        </Card>
      ))}
    </div>
  );
}

// ── Reward info card ──────────────────────────────────────────────

function RewardInfoCard() {
  return (
    <Card className="border-indigo-200/60 bg-gradient-to-br from-indigo-50/60 to-white shadow-soft">
      <CardContent className="p-5">
        <div className="flex items-start gap-3">
          <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-indigo-100">
            <Gift className="h-4.5 w-4.5 text-indigo-600" />
          </div>
          <div>
            <p className="text-sm font-semibold text-foreground">How rewards work</p>
            <p className="mt-1 text-sm text-muted-foreground leading-relaxed">
              For every <strong className="text-foreground">3 users</strong> who sign up and upgrade to a paid plan
              through your referral link, you earn <strong className="text-foreground">1 month free</strong> on your
              current plan. Rewards are applied automatically and stack indefinitely.
            </p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

// ── Referral table ────────────────────────────────────────────────

function ReferralTable() {
  const { data: referrals = [], isLoading, isError, refetch } = useReferrals();

  if (isLoading) {
    return (
      <Card className="border-border/50 shadow-soft">
        <CardHeader>
          <CardTitle className="text-base">Your referrals</CardTitle>
        </CardHeader>
        <CardContent className="space-y-2">
          {Array.from({ length: 4 }).map((_, i) => (
            <Skeleton key={i} className="h-10 w-full rounded-lg" />
          ))}
        </CardContent>
      </Card>
    );
  }

  if (isError) {
    return (
      <Card className="border-border/50 shadow-soft">
        <CardHeader>
          <CardTitle className="text-base">Your referrals</CardTitle>
        </CardHeader>
        <CardContent>
          <ErrorState
            title="Failed to load referrals"
            description="There was a problem fetching your referral history."
            onRetry={() => void refetch()}
          />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="border-border/50 shadow-soft">
      <CardHeader>
        <CardTitle className="text-base">Your referrals</CardTitle>
        <CardDescription>
          {referrals.length > 0
            ? `${referrals.length} referral${referrals.length !== 1 ? "s" : ""} total`
            : "No referrals yet — share your link to get started"}
        </CardDescription>
      </CardHeader>
      <CardContent>
        {referrals.length === 0 ? (
          <div className="rounded-xl border border-dashed border-border/50 py-12 text-center">
            <Gift className="mx-auto mb-3 h-10 w-10 text-muted-foreground/30" />
            <p className="text-sm font-medium text-foreground">No referrals yet</p>
            <p className="mt-1 text-xs text-muted-foreground max-w-xs mx-auto">
              Share your referral link above. When someone signs up through your link, they appear here.
            </p>
          </div>
        ) : (
          <div className="rounded-xl border border-border/50 overflow-hidden">
            <Table>
              <TableHeader>
                <TableRow className="bg-muted/40 hover:bg-muted/40">
                  <TableHead>Email</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Date</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {referrals.map((referral) => {
                  // Mask email: show first 3 chars + domain
                  const [local, domain] = referral.referred_email.split("@");
                  const maskedEmail = `${local.slice(0, 3)}***@${domain ?? ""}`;

                  return (
                    <TableRow key={referral.id}>
                      <TableCell className="font-mono text-sm text-foreground/80">
                        {maskedEmail}
                      </TableCell>
                      <TableCell>
                        <Badge
                          className={`text-2xs border-0 px-2 py-0.5 ${STATUS_CLASSES[referral.status]}`}
                        >
                          {STATUS_LABELS[referral.status]}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
                        {new Date(referral.created_at).toLocaleDateString("en-US", {
                          month: "short",
                          day: "numeric",
                          year: "numeric",
                        })}
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

// ── Page ──────────────────────────────────────────────────────────

const ReferralsPage = () => {
  return (
    <PageTransition>
      <div className="space-y-6">
        <PageHeader
          title="Refer & Earn"
          description="Share ConvertScan with your network and earn free months for every conversion"
        />

        <RewardInfoCard />
        <ReferralLinkCard />
        <ReferralStatsCards />
        <ReferralTable />
      </div>
    </PageTransition>
  );
};

export default ReferralsPage;

