const [submitting, setSubmitting] = useState(false);
const [googleLoading, setGoogleLoading] = useState(false);
const createReferral = useCreateReferral();

// Build post-signup redirect destination from query params
const redirectPath = searchParams.get("redirect");
const redirectUrl = searchParams.get("url");
const postSignupDest = redirectPath
  ? redirectUrl
    ? `${redirectPath}?url=${encodeURIComponent(redirectUrl)}`
    : redirectPath
  : "/dashboard";

// Capture ?ref= param on mount and persist to localStorage
useEffect(() => {
  const refCode = searchParams.get("ref");
  if (refCode) {
    localStorage.setItem(REFERRAL_STORAGE_KEY, refCode);
  }
}, [searchParams]);

// Redirect if already authenticated
useEffect(() => {
  if (!loading && user) {
    navigate(postSignupDest, { replace: true });
  }
}, [user, loading, navigate, postSignupDest]);

const handleSubmit = async (e: React.FormEvent) => {
  e.preventDefault();

  if (!name.trim()) { toast.error("Name is required."); return; }
  if (!email.trim()) { toast.error("Email is required."); return; }
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { toast.error("Enter a valid email address."); return; }
  if (!password) { toast.error("Password is required."); return; }
  if (password.length < 8) { toast.error("Password must be at least 8 characters."); return; }

  setSubmitting(true);
  const { error, data } = await signUp(email, password, name.trim());
  setSubmitting(false);

  if (error) {
    toast.error(error.message ?? "Sign up failed. Please try again.");
    return;
  }

  // Process referral if a code was stored
  const storedCode = localStorage.getItem(REFERRAL_STORAGE_KEY);
  if (storedCode && data?.user?.id) {
    createReferral.mutate({
      referrerCode: storedCode,
      referredEmail: email.trim(),
      referredId: data.user.id,
    });
    localStorage.removeItem(REFERRAL_STORAGE_KEY);
  }

  toast.success("Account created! Check your email to confirm your address.");
  navigate(postSignupDest, { replace: true });
};

