import { useEffect } from "react";
import { useNavigate } from "react-router-dom";
import supabase from "@/lib/supabase";

const REFERRAL_STORAGE_KEY = "convertscan:referral_code";

/**
 * Handles the OAuth / magic-link redirect from Supabase.
 * Supabase processes the URL hash automatically; we just wait
 * for the session to resolve and then forward the user.
 *
 * Also processes any pending referral created during signup:
 * reads convertscan:referral_code from localStorage and creates
 * the referral row if the code resolves to a valid referrer.
 */
export default function AuthCallback() {
  const navigate = useNavigate();

  useEffect(() => {
    supabase.auth.getSession().then(async ({ data: { session } }) => {
      if (session) {
        // Process pending referral (best-effort, never blocks navigation)
        const storedCode = localStorage.getItem(REFERRAL_STORAGE_KEY);
        const storedEmail = localStorage.getItem(`${REFERRAL_STORAGE_KEY}:email`);
        if (storedCode && session.user) {
          try {
            const { data: referrer } = await supabase
              .from("profiles")
              .select("id")
              .eq("referral_code", storedCode)
              .single();

            if (referrer && referrer.id !== session.user.id) {
              await supabase.from("referrals").insert({
                referrer_id: referrer.id,
                referred_email: storedEmail ?? session.user.email ?? "",
                referred_id: session.user.id,
                status: "signed_up",
              });
            }
          } catch {
            // Silently ignore — invalid code or duplicate insert
          } finally {
            localStorage.removeItem(REFERRAL_STORAGE_KEY);
            localStorage.removeItem(`${REFERRAL_STORAGE_KEY}:email`);
          }
        }

        navigate("/dashboard", { replace: true });
      } else {
        navigate("/login", { replace: true });
      }
    });
  }, [navigate]);

  return (
    <div className="flex min-h-screen items-center justify-center bg-background">
      <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
    </div>
  );
}

